import type { Vec3 } from '../contracts/math';
import type { InputSnapshot } from '../input/InputManager';
import { resolveCameraPosition, type CameraCollisionOptions, type CameraRaycaster } from './CameraCollision';

export interface CameraState {
  readonly position: Vec3;
  readonly target: Vec3;
  readonly yaw: number;
  readonly pitch: number;
  readonly distance: number;
}

export interface CameraControllerOptions {
  target?: Vec3;
  yaw?: number;
  pitch?: number;
  distance?: number;
  minDistance?: number;
  maxDistance?: number;
  minPitch?: number;
  maxPitch?: number;
  rotationSensitivity?: number;
  zoomSensitivity?: number;
  panSpeed?: number;
  raycaster?: CameraRaycaster;
  collision?: CameraCollisionOptions;
}

const DEFAULT_TARGET: Vec3 = { x: 0, y: 0, z: 0 };
const DEFAULT_YAW = Math.PI;
const DEFAULT_PITCH = 0.42;
const DEFAULT_DISTANCE = 6;
const DEFAULT_MIN_DISTANCE = 0.75;
const DEFAULT_MAX_DISTANCE = 20;
const DEFAULT_MIN_PITCH = -0.2;
const DEFAULT_MAX_PITCH = 1.25;
const DEFAULT_ROTATION_SENSITIVITY = 0.005;
const DEFAULT_ZOOM_SENSITIVITY = 0.01;
const DEFAULT_PAN_SPEED = 5;
const MAX_FRAME_SECONDS = 0.25;

const clamp = (value: number, min: number, max: number): number => Math.min(max, Math.max(min, value));
const finiteOr = (value: number | undefined, fallback: number): number =>
  value !== undefined && Number.isFinite(value) ? value : fallback;
const copy = (value: Vec3): Vec3 => ({ x: value.x, y: value.y, z: value.z });

/**
 * Renderer-agnostic orbit camera state for gameplay and presentation layers.
 * The owning renderer may map `state.position` and `state.target` to Three.js.
 */
export class CameraController {
  private readonly defaults: Required<Omit<CameraControllerOptions, 'target' | 'raycaster' | 'collision'>>;
  private readonly raycaster?: CameraRaycaster;
  private readonly collision?: CameraCollisionOptions;
  private target: Vec3;
  private yaw: number;
  private pitch: number;
  private distance: number;
  private position: Vec3;

  constructor(options: CameraControllerOptions = {}) {
    const minDistance = Math.max(0.01, finiteOr(options.minDistance, DEFAULT_MIN_DISTANCE));
    const maxDistance = Math.max(minDistance, finiteOr(options.maxDistance, DEFAULT_MAX_DISTANCE));
    const minPitch = finiteOr(options.minPitch, DEFAULT_MIN_PITCH);
    const maxPitch = Math.max(minPitch, finiteOr(options.maxPitch, DEFAULT_MAX_PITCH));
    this.defaults = {
      yaw: finiteOr(options.yaw, DEFAULT_YAW),
      pitch: clamp(finiteOr(options.pitch, DEFAULT_PITCH), minPitch, maxPitch),
      distance: clamp(finiteOr(options.distance, DEFAULT_DISTANCE), minDistance, maxDistance),
      minDistance,
      maxDistance,
      minPitch,
      maxPitch,
      rotationSensitivity: Math.max(0, finiteOr(options.rotationSensitivity, DEFAULT_ROTATION_SENSITIVITY)),
      zoomSensitivity: Math.max(0, finiteOr(options.zoomSensitivity, DEFAULT_ZOOM_SENSITIVITY)),
      panSpeed: Math.max(0, finiteOr(options.panSpeed, DEFAULT_PAN_SPEED)),
    };
    this.raycaster = options.raycaster;
    this.collision = options.collision;
    this.target = copy(options.target ?? DEFAULT_TARGET);
    this.yaw = this.defaults.yaw;
    this.pitch = this.defaults.pitch;
    this.distance = this.defaults.distance;
    this.position = this.target;
    this.recalculate();
  }

  get state(): CameraState {
    return {
      position: copy(this.position),
      target: copy(this.target),
      yaw: this.yaw,
      pitch: this.pitch,
      distance: this.distance,
    };
  }

  setTarget(target: Vec3): void {
    if (!isFiniteVector(target)) return;
    this.target = copy(target);
    this.recalculate();
  }

  setOrbit(yaw: number, pitch: number, distance = this.distance): void {
    if (Number.isFinite(yaw)) this.yaw = yaw;
    if (Number.isFinite(pitch)) this.pitch = clamp(pitch, this.defaults.minPitch, this.defaults.maxPitch);
    if (Number.isFinite(distance)) this.distance = clamp(distance, this.defaults.minDistance, this.defaults.maxDistance);
    this.recalculate();
  }

  reset(target?: Vec3): void {
    if (target && isFiniteVector(target)) this.target = copy(target);
    this.yaw = this.defaults.yaw;
    this.pitch = this.defaults.pitch;
    this.distance = this.defaults.distance;
    this.recalculate();
  }

  update(deltaSeconds: number, input?: InputSnapshot): CameraState {
    if (!input) return this.state;
    if (input.wasPressed('camera-reset')) {
      this.reset();
      return this.state;
    }

    const pointer = input.pointer;
    if (Number.isFinite(pointer.deltaX)) this.yaw -= pointer.deltaX * this.defaults.rotationSensitivity;
    if (Number.isFinite(pointer.deltaY)) {
      this.pitch = clamp(
        this.pitch - pointer.deltaY * this.defaults.rotationSensitivity,
        this.defaults.minPitch,
        this.defaults.maxPitch,
      );
    }
    if (Number.isFinite(pointer.wheel)) {
      this.distance = clamp(
        this.distance + pointer.wheel * this.defaults.zoomSensitivity,
        this.defaults.minDistance,
        this.defaults.maxDistance,
      );
    }

    const dt = Number.isFinite(deltaSeconds) ? clamp(deltaSeconds, 0, MAX_FRAME_SECONDS) : 0;
    const forward = (input.isDown('camera-forward') ? 1 : 0) - (input.isDown('camera-backward') ? 1 : 0);
    const right = (input.isDown('camera-right') ? 1 : 0) - (input.isDown('camera-left') ? 1 : 0);
    if (forward || right) {
      const length = Math.hypot(forward, right);
      const amount = (this.defaults.panSpeed * dt) / length;
      const sin = Math.sin(this.yaw);
      const cos = Math.cos(this.yaw);
      this.target = {
        x: this.target.x + (sin * forward + cos * right) * amount,
        y: this.target.y,
        z: this.target.z + (cos * forward - sin * right) * amount,
      };
    }
    this.recalculate();
    return this.state;
  }

  private recalculate(): void {
    const cosPitch = Math.cos(this.pitch);
    const desired = {
      x: this.target.x + Math.sin(this.yaw) * cosPitch * this.distance,
      y: this.target.y + Math.sin(this.pitch) * this.distance,
      z: this.target.z + Math.cos(this.yaw) * cosPitch * this.distance,
    };
    this.position = this.raycaster
      ? resolveCameraPosition(this.target, desired, this.raycaster, this.collision)
      : desired;
  }
}

function isFiniteVector(value: Vec3): boolean {
  return Number.isFinite(value.x) && Number.isFinite(value.y) && Number.isFinite(value.z);
}
