import { describe, expect, it } from 'vitest';
import type { InputSnapshot } from '../input/InputManager';
import type { CameraRaycaster } from './CameraCollision';
import { CameraController } from './CameraController';

function input(overrides: Partial<InputSnapshot['pointer']> = {}, down: string[] = [], reset = false): InputSnapshot {
  return {
    pointer: { x: 0, y: 0, deltaX: 0, deltaY: 0, wheel: 0, primaryDown: false, ...overrides },
    isDown: (action) => down.includes(action),
    wasPressed: (action) => action === 'camera-reset' && reset,
    wasReleased: () => false,
  };
}

describe('CameraController', () => {
  it('creates an orbit state and exposes defensive vector copies', () => {
    const camera = new CameraController({ target: { x: 1, y: 2, z: 3 }, yaw: 0, pitch: 0, distance: 5 });
    const state = camera.state;
    expect(state.position).toEqual({ x: 1, y: 2, z: 8 });
    state.position.x = 100;
    state.target.y = 100;
    expect(camera.state.position.x).toBe(1);
    expect(camera.state.target.y).toBe(2);
  });

  it('applies pointer orbit, zoom limits and diagonal WASD panning', () => {
    const camera = new CameraController({ yaw: 0, pitch: 0, distance: 5, minDistance: 3, maxDistance: 6, panSpeed: 4 });
    const state = camera.update(1, input({ deltaX: 10, deltaY: -1000, wheel: 1000 }, ['camera-forward', 'camera-right']));
    expect(state.pitch).toBe(1.25);
    expect(state.distance).toBe(6);
    expect(Math.hypot(state.target.x, state.target.z)).toBeCloseTo(4);
  });

  it('restores the configured orbit without losing the followed target', () => {
    const camera = new CameraController({ yaw: 1, pitch: 0.2, distance: 4 });
    camera.setTarget({ x: 4, y: 1, z: -2 });
    camera.setOrbit(2, 0.8, 10);
    const state = camera.update(1 / 60, input({}, [], true));
    expect(state).toMatchObject({ target: { x: 4, y: 1, z: -2 }, yaw: 1, pitch: 0.2, distance: 4 });
  });

  it('uses the collision raycaster to keep the camera in front of obstacles', () => {
    const raycaster: CameraRaycaster = { cast: () => ({ distance: 2 }) };
    const camera = new CameraController({ yaw: 0, pitch: 0, distance: 6, raycaster, collision: { clearance: 0.5 } });
    expect(camera.state.position).toEqual({ x: 0, y: 0, z: 1.5 });
  });
});
